SELECT COUNT(*) AS compared_rows, COUNTIF(a.payout_id IS NULL OR g.payout_id IS NULL OR a.expected_settlement IS DISTINCT FROM g.expected_settlement OR a.actual_settlement IS DISTINCT FROM g.actual_settlement OR a.received_by_deadline IS DISTINCT FROM g.received_by_deadline OR a.last_deposit_date IS DISTINCT FROM g.last_deposit_date OR a.amount_status IS DISTINCT FROM g.amount_status OR a.timing_status IS DISTINCT FROM g.timing_status OR a.overall_status IS DISTINCT FROM g.overall_status OR a.bank_entry_count IS DISTINCT FROM g.bank_entry_count) AS mismatches
FROM actual a FULL OUTER JOIN gold g ON a.payout_id=g.payout_id;
